insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('carbon', 'intermediate', 'module', 'm01-combustion-from-the-fuel-analysis', 1, 'SECTION 11 states the oxygen demand of each component of the invented Isiokpo fuel gas. Which rule does it print?', '["c + h/2 + s - o/2, weighted by the component''s mole fraction.", "c + h/4 + s - o/2, weighted by the component''s mole fraction.", "c + h/4 + s + o/2, weighted by the component''s molar mass.", "2c + h/4 + s - o, weighted by the component''s typical LHV."]'::jsonb, 1, 'SECTION 11: the oxygen demand is c + h/4 + s - o/2 for each component, weighted by its mole fraction, with the letters read off the FUEL_REFERENCE atom counts. The weighted sum is o2PerKmolFuel, 2.089500 kmol O2 per kmol fuel.'),
  ('carbon', 'intermediate', 'module', 'm01-combustion-from-the-fuel-analysis', 2, 'In the SECTION 11 oxygen demand table for the invented Isiokpo fuel gas, which weighted figure belongs to C2H6 at a mole fraction of 0.071?', '["1.736000", "0.105000", "2.089500", "0.248500"]'::jsonb, 3, 'The C2H6 row prints c + h/4 + s - o/2 as 3.5 and a weighted 0.248500. 1.736000 is the CH4 row, 0.105000 the C3H8 row and 2.089500 the sum, which is the engine''s o2PerKmolFuel.'),
  ('carbon', 'intermediate', 'module', 'm01-combustion-from-the-fuel-analysis', 3, 'SECTION 11 prints a row by row oxygen demand for the invented Isiokpo fuel gas. Where do those per component rows come from?', '["The digest computes them from the FUEL_REFERENCE atom counts; the engine returns only the weighted total.", "combustionStoichiometry returns one weighted row per component; the digest sums them.", "The oracle''s bisection returns them, and the engine checks its 2.089500 against their sum.", "They are typed into the record with the fuel gas analysis, beside each mole fraction."]'::jsonb, 0, 'SECTION 11 labels the table "computed here from the FUEL_REFERENCE atom counts; the engine returns only the weighted total". The weighted total is o2PerKmolFuel, 2.089500. The bisection SECTION 12 names is how the oracle finds the excess air.'),
  ('carbon', 'intermediate', 'module', 'm01-combustion-from-the-fuel-analysis', 4, 'The invented Isiokpo fuel gas prints o2PerKmolFuel 2.089500 and stoichAirPerKmolFuel 9.975652. How does SECTION 11 relate the second to the first?', '["2.089500 x 28.9647, the oxygen times AIR_MOLAR_MASS, in kg of air.", "2.089500 / 31.998, the oxygen over O2_MOLAR_MASS.", "2.089500 / 0.20946, the oxygen over O2_MOLE_FRACTION_DRY_AIR.", "2.089500 x 18.5068, the oxygen times fuelMolarMassKgKmol, per kmol."]'::jsonb, 2, 'SECTION 11: the stoichiometric air is that oxygen over O2_MOLE_FRACTION_DRY_AIR, 2.089500 / 0.20946 = 9.975652. AIR_MOLAR_MASS 28.9647 and O2_MOLAR_MASS 31.998 weigh air and oxygen; 18.5068 is fuelMolarMassKgKmol.'),
  ('carbon', 'intermediate', 'module', 'm01-combustion-from-the-fuel-analysis', 5, 'Which SECTION 11 figure is the stoichiometric air for the invented Isiokpo fuel gas stated on a mass basis?', '["9.975652 kmol air per kmol fuel", "15.612763 kg air per kg fuel", "18.5068 kg fuel per kmol of fuel", "7.886152 kmol N2 per kmol fuel"]'::jsonb, 1, 'SECTION 11 prints stoichAirKgPerKgFuel 15.612763 kg air per kg fuel beside stoichAirPerKmolFuel 9.975652 kmol air per kmol fuel. 18.5068 is fuelMolarMassKgKmol, and 7.886152 is products.airN2PerKmolFuel.'),
  ('carbon', 'intermediate', 'module', 'm01-combustion-from-the-fuel-analysis', 6, 'The invented Isiokpo fuel gas carries CO2 at a mole fraction of 0.025. Where does SECTION 11 put that 0.025 kmol in the combustion products?', '["Inside products.fuelN2PerKmolFuel, beside the fuel''s nitrogen.", "Inside products.airN2PerKmolFuel, 7.886152.", "Inside products.co2PerKmolFuel, 1.098000 kmol per kmol fuel.", "Nowhere in the products: the analysis drops inerts before burning."]'::jsonb, 2, 'SECTION 11: the CO2 in the fuel has c = 1 and o = 2, so it demands no oxygen and passes into the flue gas; the 0.025 kmol of fuel CO2 is inside products.co2PerKmolFuel above. The fuel''s nitrogen leaves as products.fuelN2PerKmolFuel 0.015000.'),
  ('carbon', 'intermediate', 'module', 'm01-combustion-from-the-fuel-analysis', 7, 'SECTION 11 takes the CO2 out of the invented Isiokpo analysis and renormalises the rest. What does it print?', '["o2PerKmolFuel 2.089500 and lhvMJPerKmolFuel 862.5564", "o2PerKmolFuel 2.143077 and lhvMJPerKmolFuel 840.9925", "o2PerKmolFuel 2.089500 and lhvMJPerKmolFuel 930.6273", "o2PerKmolFuel 2.143077 and lhvMJPerKmolFuel 862.5564"]'::jsonb, 3, 'With the CO2 taken out and the rest renormalised, SECTION 11 prints o2PerKmolFuel 2.143077 and lhvMJPerKmolFuel 862.5564, and reads the pair as: the inerts dilute the fuel. The analysis as given prints 2.089500 and 840.9925; 930.6273 is its hhvMJPerKmolFuel.'),
  ('carbon', 'intermediate', 'module', 'm01-combustion-from-the-fuel-analysis', 8, 'The invented Isiokpo analysis carries N2 at 0.015. How does SECTION 11 report that nitrogen in the flue gas?', '["As products.fuelN2PerKmolFuel 0.015000, carried separately from the air''s nitrogen.", "Inside products.airN2PerKmolFuel 7.886152, weighed with the air''s own nitrogen.", "As a share of products.h2oPerKmolFuel 2.033000, since it carries no carbon or sulphur.", "Not at all: the engine drops every inert row of FUEL_REFERENCE before it burns."]'::jsonb, 0, 'SECTION 11 prints products.fuelN2PerKmolFuel 0.015000 and states that the fuel''s nitrogen is carried separately from the air''s. products.airN2PerKmolFuel 7.886152 is the air''s nitrogen and 2.033000 is the water. The inert CO2 row is kept too: it passes into products.co2PerKmolFuel.'),
  ('carbon', 'intermediate', 'module', 'm01-combustion-from-the-fuel-analysis', 9, 'energyEfficiency.ATMOSPHERIC_N2_MOLAR_MASS prints 28.1610. What do SECTION 1 and SECTION 11 say it is?', '["The N2 row of FUEL_REFERENCE, 28.014 kg/kmol, printed to four decimals after rounding.", "The air''s non-oxygen part, argon included, derived by the engine from three air constants.", "The IUPAC nitrogen of ATOMIC_WEIGHT, N 14.007, doubled and corrected for the fuel''s N2.", "A typed constant for air''s nitrogen alone, with argon carried in AIR_MOLAR_MASS 28.9647."]'::jsonb, 1, 'SECTION 1 prints it as derived by the engine from the three air constants above it. SECTION 11: the air''s non-oxygen part leaves as atmospheric nitrogen at ATMOSPHERIC_N2_MOLAR_MASS, which carries air''s argon. FUEL_REFERENCE''s N2 row is 28.014.'),
  ('carbon', 'intermediate', 'module', 'm01-combustion-from-the-fuel-analysis', 10, 'Which formula does SECTION 1 print for how the engine derives ATMOSPHERIC_N2_MOLAR_MASS?', '["(AIR_MOLAR_MASS - O2_MOLE_FRACTION_DRY_AIR x O2_MOLAR_MASS) / O2_MOLE_FRACTION_DRY_AIR", "(AIR_MOLAR_MASS - O2_MOLAR_MASS) / (1 - O2_MOLE_FRACTION_DRY_AIR)", "(AIR_MOLAR_MASS - O2_MOLE_FRACTION_DRY_AIR x O2_MOLAR_MASS) / (1 - O2_MOLE_FRACTION_DRY_AIR)", "AIR_MOLAR_MASS - O2_MOLE_FRACTION_DRY_AIR x O2_MOLAR_MASS"]'::jsonb, 2, 'SECTION 1 prints that formula beside 28.1610. Each wrong option moves one term: the divisor cut to the oxygen fraction alone, the O2 molar mass dropped from the product, or the whole product taken off with no divisor.'),
  ('carbon', 'intermediate', 'module', 'm01-combustion-from-the-fuel-analysis', 11, 'SECTION 11 prints a mass balance at 3 percent stack oxygen for the invented Isiokpo fuel. What makes up its in side?', '["The fuel molar mass plus the actual air times AIR_MOLAR_MASS.", "The engine dry flue gas plus the engine moisture, both per kmol of fuel.", "The fuel molar mass plus the actual air times O2_MOLAR_MASS.", "The stoichiometric air times ATMOSPHERIC_N2_MOLAR_MASS, argon and all."]'::jsonb, 0, 'SECTION 11: fuel plus air in (fuel molar mass plus actual air times AIR_MOLAR_MASS) 351.0222 kg per kmol of fuel. The engine dry flue gas plus engine moisture is the out side, also 351.0222.'),
  ('carbon', 'intermediate', 'module', 'm01-combustion-from-the-fuel-analysis', 12, 'The SECTION 11 mass balance at 3 percent stack oxygen prints out less in as 0.000001 kg per kmol of fuel. What is that figure?', '["An output combustionStoichiometry returns.", "The weight of argon the engine drops from the flue gas.", "The fuel CO2 counted on both sides of the balance.", "The digest''s own arithmetic on the engine''s two sides."]'::jsonb, 3, 'SECTION 11 marks the out less in row computed here: the generator''s arithmetic on the engine''s in side and out side, 351.0222 each. The same section says air''s argon is carried at ATMOSPHERIC_N2_MOLAR_MASS, and SECTION 25 lists the balance as closing.'),
  ('carbon', 'intermediate', 'module', 'm01-combustion-from-the-fuel-analysis', 13, 'energyEfficiency.FUEL_REFERENCE carries atom counts and typical heating values. Which does FUEL_REFERENCE_NOTE say drives the stoichiometry?', '["The typical LHV column, which the note calls governing.", "The atom counts, which the note calls definitional.", "The inert flag, which drops CO2 and N2 from the demand.", "The typical HHV column, which a measured value replaces."]'::jsonb, 1, 'FUEL_REFERENCE_NOTE, verbatim: "Atom counts are definitional and drive the stoichiometry. Heating values are typical: the fuel analysis governs, and a measured value should replace these." The inert rows are kept: SECTION 11 passes the fuel CO2 into products.co2PerKmolFuel.'),
  ('carbon', 'intermediate', 'module', 'm01-combustion-from-the-fuel-analysis', 14, 'SECTION 1 prints the CO2 row of FUEL_REFERENCE, PRODUCT_MOLAR_MASS.CO2 and carbonAbatement.MW_CO2. What does it say about their molar masses?', '["They are one number, 44.009, going into the fuel and out in the flue gas.", "The fuel row prints 44.097 and the flue gas products print 44.009.", "The fuel row prints 44.009 and the flue gas products print 28.014.", "Each module rounds its own, so 44.009 and 44.097 both appear."]'::jsonb, 0, 'SECTION 1: the CO2 row, PRODUCT_MOLAR_MASS.CO2 and carbonAbatement.MW_CO2 are one number, 44.009, and an inert CO2 in the fuel weighs the same going in as it does in the flue gas. 44.097 is propane''s molar mass and 28.014 is N2.'),
  ('carbon', 'intermediate', 'module', 'm01-combustion-from-the-fuel-analysis', 15, 'How much water does each kmol of the invented Isiokpo fuel gas make when burned, as products.h2oPerKmolFuel?', '["1.098000", "0.015000", "2.033000", "2.089500"]'::jsonb, 2, 'SECTION 11 prints products.h2oPerKmolFuel 2.033000. 1.098000 is products.co2PerKmolFuel, 0.015000 products.fuelN2PerKmolFuel, and 2.089500 the oxygen demand o2PerKmolFuel.'),
  ('carbon', 'intermediate', 'module', 'm02-excess-air-and-stack-oxygen', 1, 'SECTION 12 prints the assumption behind excessAirFromFlueOxygen. According to it, how does a stack making carbon monoxide read?', '["As if it had less excess air than it has.", "As the same excess air, at a lower efficiency.", "As if it had more excess air than it has.", "As a refusal: the engine will not read a CO stack."]'::jsonb, 2, 'The engine''s assumption, verbatim: "Complete combustion. An oxygen reading alone cannot see carbon monoxide, so a stack making CO will read as if it had more excess air than it has." The sentence names a direction and prints no size.'),
  ('carbon', 'intermediate', 'module', 'm02-excess-air-and-stack-oxygen', 2, 'The invented Isiokpo heater reads 5.5 percent dry stack oxygen. What excess air does SECTION 12 print for that reading?', '["32.1223 percent", "13.9199 percent", "21.2938 percent", "55.7461 percent"]'::jsonb, 0, 'The 5.5 row prints excess air 32.1223 percent. 13.9199 percent is the 2.8 row, 21.2938 percent the 4 row and 55.7461 percent the 8 row.'),
  ('carbon', 'intermediate', 'module', 'm02-excess-air-and-stack-oxygen', 3, 'At a dry stack oxygen of 2.8 percent, which SECTION 12 figure is the actual air for the invented Isiokpo fuel gas?', '["11.364257", "10.387757", "12.420757", "10.925631"]'::jsonb, 0, 'The 2.8 row prints actual air 11.364257, dry flue gas 10.387757 and wet flue gas 12.420757 kmol per kmol fuel. 10.925631 is the actual air in the 2 row.'),
  ('carbon', 'intermediate', 'module', 'm02-excess-air-and-stack-oxygen', 4, 'In every SECTION 12 row the wet flue gas less the dry flue gas is 2.033000 kmol per kmol fuel. What does the digest say that difference is?', '["The oxygen the excess air carries through the stack.", "The water the hydrogen makes, products.h2oPerKmolFuel.", "The fuel''s CO2 and nitrogen, which pass through unburned.", "The argon that ATMOSPHERIC_N2_MOLAR_MASS carries."]'::jsonb, 1, 'SECTION 12: the wet flue gas less the dry is the water the hydrogen makes, 2.033000 in every row, and products.h2oPerKmolFuel is 2.033000 (SECTION 11).'),
  ('carbon', 'intermediate', 'module', 'm02-excess-air-and-stack-oxygen', 5, 'Down the whole oxygen table, subtracting actual air from dry flue gas always gives -0.976500. Which reading of that constant does the digest print?', '["Each extra kilomole of air adds 2.033000 kmol of water to the stack.", "Above 5.5 percent the dry flue gas grows faster than the actual air.", "The oxygen demand falls by 2.089500 kmol for every kilomole of air.", "Each extra kilomole of air leaves as a kilomole of dry flue gas."]'::jsonb, 3, 'SECTION 12: the dry flue gas less the actual air is fixed, because each extra kilomole of air leaves as a kilomole of dry flue gas. The figure prints as -0.976500 from 0 to 12 percent. The 2.033000 is the wet less dry, the water, and the oxygen demand stays at 2.089500.'),
  ('carbon', 'intermediate', 'module', 'm02-excess-air-and-stack-oxygen', 6, 'SECTION 12 prints two calls to excessAirFromFlueOxygen, one at 21 percent and one at -1 percent dry stack oxygen. What does the engine answer?', '["21 percent is refused as above the oxygen in dry air, and -1 percent is read as 0 percent, excess air 0.0000 percent.", "Both are refused with the message that a measured dry stack oxygen is required, since neither is a real reading.", "Both are refused with the same message, the one that states the bound of 0 percent or more and below 20.946 percent.", "Neither is refused: 21 percent prints above the 121.0076 percent of the 12 row and -1 percent prints below zero."]'::jsonb, 2, 'SECTION 12 prints both calls answered by one refusal: "Stack oxygen must be 0 percent or more and below 20.946 percent, the oxygen in dry air. A reading of 20.946 percent is air with no fuel burned." The required-reading message answers a blank.'),
  ('carbon', 'intermediate', 'module', 'm02-excess-air-and-stack-oxygen', 7, 'The dry stack oxygen box is left blank on a call for the invented Isiokpo fuel gas. What does excessAirFromFlueOxygen return?', '["REFUSED: A measured dry stack oxygen is required.", "REFUSED: Valid stoichiometry is required.", "Excess air 0.0000 percent: a blank is read as a reading of 0.", "REFUSED: Stack oxygen must be 0 percent or more and below 20.946 percent, the oxygen in dry air. A reading of 20.946 percent is air with no fuel burned."]'::jsonb, 0, 'SECTION 12 prints the blank reading refused with its own message, "A measured dry stack oxygen is required." The 0 row, excess air 0.0000 percent, is what a typed 0 returns. The stoichiometry message answers a call with no stoichiometry.'),
  ('carbon', 'intermediate', 'module', 'm02-excess-air-and-stack-oxygen', 8, 'SECTION 12 says the excess air is solved one way in the engine and found another way by the oracle. Which pairing does it print?', '["The engine finds E by bisection; the oracle solves the closed form on the stoichiometric terms.", "The engine solves a closed form; the oracle finds the same E by bisection on the full dry flue gas.", "Both solve the closed form, the engine on the dry flue gas and the oracle on the wet flue gas.", "The engine reads E between the printed rows, and the oracle finds it by bisection on wet gas."]'::jsonb, 1, 'SECTION 12 prints that the relation is solved in closed form, and that the oracle finds the same E by bisection on the full dry flue gas (SECTION 26). The table prints the engine''s answers.'),
  ('carbon', 'intermediate', 'module', 'm02-excess-air-and-stack-oxygen', 9, 'SECTION 12 states the relation the engine solves, with E the excess-air fraction. Which is it?', '["E x oxygen demand / (stoichiometric wet products + E x stoichiometric air) = measured fraction", "E x stoichiometric air / (stoichiometric dry products + E x oxygen demand) = measured fraction", "oxygen demand / (stoichiometric dry products + E x stoichiometric air) = measured fraction", "E x oxygen demand / (stoichiometric dry products + E x stoichiometric air) = measured fraction"]'::jsonb, 3, 'SECTION 12: E times the oxygen demand over (the stoichiometric dry products plus E times the stoichiometric air) equals the measured fraction.'),
  ('carbon', 'intermediate', 'module', 'm02-excess-air-and-stack-oxygen', 10, 'The first SECTION 12 refusal is labelled "all air", a dry stack oxygen of 20.946 percent. What does the refusal''s second sentence say that reading is?', '["Air with no fuel burned.", "A stack at the 12 percent row''s 121.0076 percent excess air.", "The stoichiometric case, with excess air of 0.0000 percent.", "A stack making CO that reads as though it had more air."]'::jsonb, 0, 'The second sentence names 20.946 percent as air with no fuel burned, and SECTION 1 prints O2_MOLE_FRACTION_DRY_AIR 0.20946. 121.0076 percent is the excess air of the 12 row, the highest row SECTION 12 prints, and 0.0000 percent that of its 0 row. The CO sentence is the engine''s assumption, printed above the table.'),
  ('carbon', 'intermediate', 'module', 'm02-excess-air-and-stack-oxygen', 11, 'Which row of the SECTION 12 table carries 4.5228 percent in its excess air column?', '["2 percent", "2.8 percent", "1 percent", "4 percent"]'::jsonb, 2, 'The 1 row prints excess air 4.5228 percent and actual air 10.426827 kmol per kmol fuel. The 2 row prints 9.5230, the 2.8 row 13.9199 and the 4 row 21.2938 percent.'),
  ('carbon', 'intermediate', 'module', 'm02-excess-air-and-stack-oxygen', 12, 'excessAirFromFlueOxygen is called with a reading of 5.5 percent and no stoichiometry. What does SECTION 12 print?', '["32.1223 percent excess air, read from the table row.", "REFUSED: Valid stoichiometry is required.", "REFUSED: A measured dry stack oxygen is required.", "13.180063 kmol of air per kmol, with no excess air."]'::jsonb, 1, 'SECTION 12 prints the call with no stoichiometry refused: "Valid stoichiometry is required." 32.1223 percent and 13.180063 are the 5.5 row with the Isiokpo stoichiometry supplied.'),
  ('carbon', 'intermediate', 'module', 'm02-excess-air-and-stack-oxygen', 13, 'Which unit goes with the 13.180063 printed in the actual air column?', '["kmol of air per kmol of fuel", "kg of air per kg of fuel", "kmol O2 per kmol of fuel", "percent of the stoichiometric air"]'::jsonb, 0, 'The SECTION 12 column is headed actual air kmol per kmol fuel. kg air per kg fuel is the unit of stoichAirKgPerKgFuel 15.612763, kmol O2 per kmol fuel the unit of o2PerKmolFuel 2.089500, and the excess air column is the one in percent.'),
  ('carbon', 'intermediate', 'module', 'm02-excess-air-and-stack-oxygen', 14, 'SECTION 14 prints the refusal for a blank minimum safe stack oxygen. On what does it say the carbon monoxide point depends?', '["The stack oxygen, the fuel and the excess air.", "The stack temperature and radiation loss.", "The fuel analysis and its typical heating value.", "The burner, the fuel and the draught control."]'::jsonb, 3, 'The refusal, verbatim: "A minimum safe stack oxygen is required and is not defaulted. Below some excess air a burner makes carbon monoxide, and where that point sits depends on the burner, the fuel and the draught control." At Isiokpo the floor is 2 percent, declared after a combustion test (invented).'),
  ('carbon', 'intermediate', 'module', 'm02-excess-air-and-stack-oxygen', 15, 'A stack reading no oxygen at all: how does that first row of the table compare with SECTION 11?', '["Excess air 0.0000 percent and actual air 8.999152, the dry flue gas of that row.", "Excess air 4.5228 percent and actual air 10.426827, the first reading it answers.", "Excess air 0.0000 percent and actual air 9.975652, equal to stoichAirPerKmolFuel.", "A refusal, since a reading of 0 percent is read the same as a blank reading."]'::jsonb, 2, 'The 0 row prints excess air 0.0000, actual air 9.975652, dry flue gas 8.999152 and wet flue gas 11.032152 kmol per kmol fuel; SECTION 11 prints stoichAirPerKmolFuel 9.975652. 4.5228 and 10.426827 are the 1 row. A blank is refused with its own message.'),
  ('carbon', 'intermediate', 'module', 'm03-stack-loss-efficiency', 1, 'The stack loss section prints the invented Isiokpo heater at its current 5.5 percent stack oxygen. What efficiency does it print on HHV?', '["79.2343 percent", "86.4029 percent", "77.9288 percent", "87.8476 percent"]'::jsonb, 2, 'The current HHV row prints 77.9288 percent. 79.2343 percent is the target HHV row at 2.8 percent oxygen, 86.4029 percent the current LHV row and 87.8476 percent the target LHV row.'),
  ('carbon', 'intermediate', 'module', 'm03-stack-loss-efficiency', 2, 'The stack loss section prints a difference of 8.4741 percentage points for the invented Isiokpo heater. Between which two figures?', '["86.4029 on LHV and 77.9288 on HHV, one heater at one oxygen reading.", "86.4029 and 87.8476 on LHV, the heater before and after tuning.", "77.9288 and 79.2343 on HHV, the heater before and after tuning.", "The HHV moisture loss 11.2450 and LHV total loss 13.5971."]'::jsonb, 0, 'The stack loss section: the same heater at the same oxygen reads 86.4029 percent on LHV and 77.9288 percent on HHV, a difference of 8.4741 percentage points (computed here from the engine''s figures). The tuning pairs are one basis each, current against target.'),
  ('carbon', 'intermediate', 'module', 'm03-stack-loss-efficiency', 3, 'On the HHV basis, what does stackLossEfficiency''s moisture note count as lost from the flue gas water?', '["Only the sensible heat of the water vapour is a loss, as HHV never counted the latent heat.", "The latent heat of all the water in the stack is a loss, the air''s humidity included.", "Neither heat of the water is a loss on HHV, because HHV counted both of them as available.", "The latent heat of the water made from hydrogen is a loss, because HHV counted it as available."]'::jsonb, 3, 'The HHV note, verbatim: "On HHV the latent heat of the water made from hydrogen is a loss, because HHV counted it as available." The LHV note: "On LHV only the sensible heat of the water vapour is a loss, because LHV never counted the latent heat as available."'),
  ('carbon', 'intermediate', 'module', 'm03-stack-loss-efficiency', 4, 'How does the HHV moisture loss change when the heater is tuned from its current row to its target row?', '["11.2450 falling to 9.0262 percent", "11.2450 percent in both rows", "1.8088 percent in both of the rows", "9.0262 falling to 7.7207 percent"]'::jsonb, 1, 'Both HHV rows print a moisture loss of 11.2450 and both LHV rows 1.8088. The HHV dry flue gas loss is what moves, 9.0262 to 7.7207 percent.'),
  ('carbon', 'intermediate', 'module', 'm03-stack-loss-efficiency', 5, 'The stack loss section relates the invented Isiokpo heater''s HHV dry flue gas loss, 9.0262 percent, to its LHV dry loss at 5.5 percent. How?', '["9.9883 x 930.6273 / 840.9925, the heating values swapped.", "9.9883 less 8.4741 plus the 1.8000 radiation loss, carried on both bases.", "9.9883 x 840.9925 / 930.6273: the same kilojoules over a different heating value.", "9.9883 x 77.9288 / 86.4029, the two current efficiencies in place of the heating values."]'::jsonb, 2, 'The stack loss section: the dry flue gas loss is the same kilojoules on both bases, divided by a different heating value: 9.9883 x 840.9925 / 930.6273 = 9.0262 (computed here). 840.9925 and 930.6273 are the fuel''s lhvMJPerKmolFuel and hhvMJPerKmolFuel; 77.9288 and 86.4029 are the current efficiencies, which the printed relation does not use.'),
  ('carbon', 'intermediate', 'module', 'm03-stack-loss-efficiency', 6, 'stackLossEfficiency is called for the invented Isiokpo heater with the radiation and convection loss left blank. What does the stack loss section print?', '["REFUSED: A radiation and convection loss is required and is not defaulted. It comes off a published chart against surface area and firing rate, which this module does not reproduce.", "REFUSED: A stack temperature and a combustion air temperature are required.", "REFUSED: The radiation and convection loss cannot be negative: a loss below zero would add to the efficiency.", "REFUSED: On a higher-heating-value basis the moisture loss needs both the latent heat of water and the vapour specific heat."]'::jsonb, 0, 'The stack loss section prints the blank radiation loss refused with that sentence. The other three are the refusals the stack loss section prints for a blank stack temperature, a radiation loss of -3 and an HHV call with no latent heat.'),
  ('carbon', 'intermediate', 'module', 'm03-stack-loss-efficiency', 7, 'The invented Isiokpo radiation and convection loss is raised from 1.8 to 2.5 percent. What current LHV efficiency does the stack loss section print?', '["87.2029 percent", "86.4029 percent", "87.8476 percent", "85.7029 percent"]'::jsonb, 3, 'The radiation table prints 87.2029 at 1.0, 86.4029 at 1.8 and 85.7029 at 2.5 percent; 87.8476 is the target LHV row at 2.8 percent oxygen. The digest''s sentence over the table is that the radiation loss moves the efficiency one for one.'),
  ('carbon', 'intermediate', 'module', 'm03-stack-loss-efficiency', 8, 'A radiation and convection loss of -3 is typed for the invented Isiokpo heater. What comes back?', '["No refusal: the loss enters the ledger as typed, and the current LHV efficiency prints above the 87.2029 percent of the 1.0 row.", "REFUSED: The radiation and convection loss cannot be negative: a loss below zero would add to the efficiency.", "REFUSED: A radiation and convection loss is required and is not defaulted. It comes off a published chart against surface area and firing rate, which this module does not reproduce.", "No refusal: a negative loss is read as 0 and the unburned loss of 0.0000 is carried instead."]'::jsonb, 1, 'The stack loss section prints the call with -3 refused: "The radiation and convection loss cannot be negative: a loss below zero would add to the efficiency." SECTION 25 lists it among the rules in force: a negative radiation or unburned loss is refused.'),
  ('carbon', 'intermediate', 'module', 'm03-stack-loss-efficiency', 9, 'stackLossEfficiency is called with the heating value basis "gross". What does the engine answer?', '["REFUSED: The heating value basis must be LHV or HHV. \"gross\" is neither, and an efficiency on an unknown basis cannot be compared with anything.", "No refusal: gross is read as HHV and the current row prints 77.9288 percent.", "No refusal: gross is read as LHV and the current row prints 86.4029 percent.", "REFUSED: A radiation and convection loss is required and is not defaulted. It comes off a published chart against surface area and firing rate, which this module does not reproduce."]'::jsonb, 0, 'The stack loss section prints the call refused, and a blank basis gets the same message with "" in place of "gross". The radiation refusal answers a blank radiation loss.'),
  ('carbon', 'intermediate', 'module', 'm03-stack-loss-efficiency', 10, 'The basis is typed as " hhv ", lower case with spaces around it. What does the stack loss section print?', '["Basis hhv and 86.4029 percent, the current LHV row.", "A refusal: \" hhv \" is neither LHV nor HHV as typed.", "Basis HHV and 77.9288 percent, the current HHV row.", "Basis LHV and 86.4029 percent, since case is unread."]'::jsonb, 2, 'The stack loss section: the basis is read without regard to case or spaces and reported in capitals: " hhv " returns basis HHV and 77.9288 percent, the HHV row above.'),
  ('carbon', 'intermediate', 'module', 'm03-stack-loss-efficiency', 11, 'The stack loss section checks a relation on all four of its rows for the invented Isiokpo heater. Which one?', '["The dry and moisture losses add to the total loss, and radiation comes off the efficiency.", "The four losses add to the efficiency, and the total loss is 100 less the efficiency.", "The dry flue gas loss prints the same percent on both bases, row by row.", "The four losses add to the total loss, and the efficiency is 100 less the total loss."]'::jsonb, 3, 'The stack loss section: in every row the four losses add to the total loss and the efficiency is 100 less the total loss (checked here on all four rows). On the current LHV row that is 13.5971 and 86.4029.'),
  ('carbon', 'intermediate', 'module', 'm03-stack-loss-efficiency', 12, 'Which stack and combustion air temperatures does the stack loss section give the invented Isiokpo heater?', '["Stack 238 C, combustion air 25 C", "Stack 238 C, combustion air 28 C", "Stack 400 C, combustion air 28 C", "Stack 28 C, combustion air 238 C"]'::jsonb, 1, 'The stack loss section: stack 238 C, combustion air 28 C, both invented. 25 C is the reference temperature of the typical latent heat and 400 C the top of the typical flue gas cp range (SECTION 1). The last pairing, 28 C for the stack and 238 C for the air, swaps the two.'),
  ('carbon', 'intermediate', 'module', 'm03-stack-loss-efficiency', 13, 'Read the tuned line on LHV: which total loss and efficiency sit together there?', '["Total loss 12.1524 percent, efficiency 87.8476 percent", "Total loss 13.5971 percent, efficiency 86.4029 percent", "Total loss 20.7657 percent, efficiency 79.2343 percent", "Total loss 12.1524 percent, efficiency 86.4029 percent"]'::jsonb, 0, 'On LHV at 2.8 percent oxygen the total loss is 12.1524 and the efficiency 87.8476. The 5.5 percent line on the same basis reads 13.5971 and 86.4029, and the same target read on HHV 20.7657 and 79.2343.'),
  ('carbon', 'intermediate', 'module', 'm03-stack-loss-efficiency', 14, 'stackLossEfficiency is asked for an HHV efficiency with the latent heat of water left out. What does the stack loss section print?', '["No refusal: the HHV moisture loss is taken at the LHV figure of 1.8088 percent and the row is labelled HHV.", "No refusal: the latent heat takes the PROPERTY_REFERENCE typical value of 2442 kJ/kg and is named in a note.", "REFUSED: A radiation and convection loss is required and is not defaulted. It comes off a published chart against surface area and firing rate, which this module does not reproduce.", "REFUSED: On a higher-heating-value basis the moisture loss needs both the latent heat of water and the vapour specific heat."]'::jsonb, 3, 'The stack loss section prints the HHV call with no latent heat refused with that sentence. The typical 2442 kJ/kg is what the Isiokpo calls pass; a blank is refused. The radiation refusal answers a blank radiation loss.'),
  ('carbon', 'intermediate', 'module', 'm03-stack-loss-efficiency', 15, 'Going from the current 5.5 percent row to the target 2.8 percent row on LHV, which loss does the stack loss section print moving?', '["The moisture loss, 1.8088 to 1.8000 percent, as the water falls.", "The radiation loss, 1.8000 to 1.0 percent off the chart.", "The dry flue gas loss, 9.9883 to 8.5436 percent.", "The unburned loss, 1.8000 to 0.0000 percent."]'::jsonb, 2, 'The LHV rows print dry flue gas loss 9.9883 then 8.5436, moisture 1.8088 in both, radiation 1.8000 in both and unburned 0.0000 in both. Total loss goes from 13.5971 to 12.1524.'),
  ('carbon', 'intermediate', 'module', 'm04-what-tuning-is-worth', 1, 'SECTION 14 prints the engine''s method for the saving from tuning the invented Isiokpo heater. Which ratio does it give?', '["(target - current) / current", "(target - current) / target", "(target - current) / a hundred", "(target - current) / (target + current)"]'::jsonb, 1, 'The method, verbatim: "Fuel scales inversely with efficiency at the same duty, so the saving is (target - current) / target. Subtracting the efficiency percentages divides by a hundred instead of by the target efficiency, and understates the saving."'),
  ('carbon', 'intermediate', 'module', 'm04-what-tuning-is-worth', 2, 'The digest works the percentage-point shortcut on the invented Isiokpo figures, 410000 GJ a year on LHV. What does it print for it?', '["5923.008 GJ a year, 819.363 GJ above the engine''s saving.", "6742.370 GJ a year, the same figure the engine returns.", "8337.934 GJ a year, the figure the 2.0 percent row prints.", "5923.008 GJ a year, 819.363 GJ below the engine''s saving."]'::jsonb, 3, 'SECTION 14, computed here from the engine''s efficiencies: a saving fraction of 0.0144463600, which is 5923.008 GJ a year, 819.363 GJ below the engine''s saving. The engine''s own sentence says subtracting the percentages understates the saving. 6742.370 is annualEnergySavedGJ and 8337.934 the 2.0 row of the sweep.'),
  ('carbon', 'intermediate', 'module', 'm04-what-tuning-is-worth', 3, 'Which figure in SECTION 14 is the saving fraction of the percentage-point shortcut, the digest''s own arithmetic on the invented Isiokpo efficiencies?', '["0.0144463600", "0.0164448058", "0.0164763814", "6742.370"]'::jsonb, 0, 'SECTION 14 prints the shortcut''s fraction as 0.0144463600 and marks it computed here; the engine does not return it. 0.0164448058 is the engine''s fuelSavingFraction on LHV, 0.0164763814 the HHV fraction from the two HHV efficiencies of the stack loss section, and 6742.370 is annualEnergySavedGJ.'),
  ('carbon', 'intermediate', 'module', 'm04-what-tuning-is-worth', 4, 'The invented Isiokpo tuning is asked for a target of 1.5 percent oxygen against the 2 percent floor declared after a combustion test. What does SECTION 14 print?', '["REFUSED: The target stack oxygen is required, so that it can be checked against the declared safe floor.", "No refusal: the saving is printed above the 8337.934 GJ a year of the 2.0 row, with a note that the target sits below the floor.", "REFUSED: A target of 1.5 percent oxygen is below the 2 percent declared safe for this burner. Raise the target or re-declare the floor after a combustion test.", "REFUSED: A minimum safe stack oxygen is required and is not defaulted. Below some excess air a burner makes carbon monoxide, and where that point sits depends on the burner, the fuel and the draught control."]'::jsonb, 2, 'SECTION 14 prints the 1.5 percent target refused with that sentence, naming both figures. The target-required refusal answers a blank target and the floor refusal a blank floor. The sweep prints no row below the floor.'),
  ('carbon', 'intermediate', 'module', 'm04-what-tuning-is-worth', 5, 'A tuning call for the invented Isiokpo heater gives a current reading and a safe floor but leaves the target empty. Which answer comes back from excessAirSaving?', '["No refusal: the target is taken at the 2 percent floor and the saving prints as 8337.934 GJ a year.", "REFUSED: The target stack oxygen is required, so that it can be checked against the declared safe floor.", "No refusal: the target is taken at 2.8 percent, the Isiokpo case, and the saving prints as 6742.370 GJ.", "REFUSED: The two efficiencies are on different bases (LHV and HHV) and cannot be compared."]'::jsonb, 1, 'SECTION 14 prints the blank target refused with that sentence. 8337.934 GJ is the 2.0 row and 6742.370 GJ the 2.8 row, each a typed target. The different-bases refusal answers a current efficiency on LHV with a target on HHV.'),
  ('carbon', 'intermediate', 'module', 'm04-what-tuning-is-worth', 6, 'excessAirSaving is given a current efficiency on LHV and a target efficiency on HHV for the invented Isiokpo heater. What does SECTION 14 print?', '["No refusal: the engine converts the HHV target to LHV and prints fuelSavingPercent 1.6445.", "No refusal: basis HHV and a fuelSavingPercent of 1.6476, the HHV fraction as a percent.", "REFUSED: The target stack oxygen is required, so that it can be checked against the declared safe floor.", "REFUSED: The two efficiencies are on different bases (LHV and HHV) and cannot be compared."]'::jsonb, 3, 'SECTION 14 prints the mixed pair refused with that sentence. 1.6445 is the LHV fuelSavingPercent from two LHV efficiencies and 1.6476 the HHV figure from two HHV efficiencies. The target-required refusal answers a blank target.'),
  ('carbon', 'intermediate', 'module', 'm04-what-tuning-is-worth', 7, 'Reading the sweep table, which saving percent does the 3.5 percent target carry?', '["0.6786", "2.0336", "1.2718", "1.6445"]'::jsonb, 2, 'fuelSavingPercent 1.2718 belongs to the 3.5 percent target, beside 5214.422 GJ a year. The 4.5 target carries 0.6786, the floor at 2.0 carries 2.0336 and the Isiokpo 2.8 target 1.6445.'),
  ('carbon', 'intermediate', 'module', 'm04-what-tuning-is-worth', 8, 'Which target row of the SECTION 14 sweep sits on the declared 2 percent floor of the invented Isiokpo burner, and what does it save a year?', '["The 2.0 row, 8337.934 GJ a year", "The 2.8 row, 6742.370 GJ a year", "The 3.5 row, 5214.422 GJ a year", "The 1.5 row, a saving above 8337.934 GJ"]'::jsonb, 0, 'The sweep prints targets of 2.0, 2.8, 3.5 and 4.5 percent, every one at or above the declared floor, and the 2.0 row saves 8337.934 GJ a year at 88.1965 percent on LHV. A target of 1.5 percent against the 2 percent floor is refused.'),
  ('carbon', 'intermediate', 'module', 'm04-what-tuning-is-worth', 9, 'How does excessAirSaving arrive at annualEnergySavedGJ 6742.370 for the invented Isiokpo heater?', '["It multiplies the shortcut fraction 0.0144463600 by the 410000 GJ of fuel a year it is given.", "It multiplies fuelSavingFraction 0.0164448058 by the 410000 GJ of fuel a year it is given.", "It multiplies fuelSavingPercent 1.6445 by the heater''s duty, taken from the fuel analysis.", "It divides the 410000 GJ a year by the target efficiency of 87.8476 and subtracts the fuel."]'::jsonb, 1, 'SECTION 14 prints the fraction, 0.0164448058, and the fuel it is applied to, 410000 GJ a year on LHV (invented); annualEnergySavedGJ is 6742.370. The digest''s shortcut applies 0.0144463600 to the same fuel and gets 5923.008 GJ.'),
  ('carbon', 'intermediate', 'module', 'm04-what-tuning-is-worth', 10, 'SECTION 14 prints a saving fraction of 0.0164763814 for the same invented tuning on HHV. What does it say about the fuel figure that fraction multiplies?', '["The engine converts the 410000 GJ to HHV before it multiplies, so the basis always matches.", "The engine refuses any annual fuel figure that is not labelled with its heating value basis.", "The engine takes the fuel on HHV from the typical 890.8 and prints an annual HHV saving.", "The engine multiplies the fraction by the fuel it is given, and matching its basis is the caller''s job."]'::jsonb, 3, 'SECTION 14: "The engine multiplies a saving fraction by the annual fuel it is given, and the basis of that fuel figure is the caller''s to match." It prints no annual HHV saving in gigajoules, and the 410000 GJ it prints is stated on LHV.'),
  ('carbon', 'intermediate', 'module', 'm04-what-tuning-is-worth', 11, 'Which efficiency sits on the bottom of the engine''s saving ratio for the invented Isiokpo tuning on LHV?', '["The target efficiency, 87.8476 percent.", "The current efficiency, 86.4029 percent.", "A hundred percent, the shortcut''s divisor.", "The HHV target efficiency, 79.2343 percent."]'::jsonb, 0, 'The method: the saving is (target - current) / target, so the target efficiency sits below the line, 87.8476 percent on LHV at 2.8 percent oxygen. Dividing by a hundred is the shortcut the same sentence says understates the saving.'),
  ('carbon', 'intermediate', 'module', 'm04-what-tuning-is-worth', 12, 'What fuelSavingPercent does SECTION 14 print for the same invented tuning, 5.5 to 2.8 percent oxygen, on HHV?', '["1.6445", "2.0336", "1.6476", "1.2718"]'::jsonb, 2, 'On HHV the same tuning is a saving fraction of 0.0164763814, fuelSavingPercent 1.6476, computed from the two HHV efficiencies of the stack loss section. 1.6445 is the LHV figure, 2.0336 and 1.2718 the 2.0 and 3.5 rows of the LHV sweep.'),
  ('carbon', 'intermediate', 'module', 'm04-what-tuning-is-worth', 13, 'The sweep is run to a target of 4.5 percent oxygen. What target efficiency does that row carry?', '["87.5160 percent", "86.9933 percent", "86.4029 percent", "88.1965 percent"]'::jsonb, 1, '86.9933 percent is what the 4.5 target carries, with a saving of 2782.362 GJ a year. 87.5160 goes with 3.5 and 88.1965 with the 2.0 floor; 86.4029 is currentEfficiencyPercent, the heater at 5.5 percent.'),
  ('carbon', 'intermediate', 'module', 'm04-what-tuning-is-worth', 14, 'Which of these figures does excessAirSaving not return for the invented Isiokpo tuning?', '["fuelSavingFraction 0.0164448058", "fuelSavingPercent 1.6445 on LHV", "annualEnergySavedGJ 6742.370", "The shortcut''s 0.0144463600"]'::jsonb, 3, 'The output rows are basis, currentEfficiencyPercent, targetEfficiencyPercent, fuelSavingFraction, fuelSavingPercent and annualEnergySavedGJ. The shortcut figure sits outside that table, marked computed here.'),
  ('carbon', 'intermediate', 'module', 'm04-what-tuning-is-worth', 15, 'What basis does the SECTION 14 output carry for the invented Isiokpo tuning, and on what basis is its 410000 GJ of fuel a year stated?', '["Basis LHV, with the fuel stated on LHV.", "Basis HHV, with the fuel stated on LHV.", "Basis LHV, with the fuel stated on HHV.", "No basis output; fuel stated on HHV."]'::jsonb, 0, 'SECTION 14''s output table prints basis LHV, and its inputs are 410000 GJ of fuel a year on LHV (invented). The two efficiencies it takes, 86.4029 and 87.8476, are the LHV rows of the stack loss section.'),
  ('carbon', 'intermediate', 'module', 'm05-steam-condensate-and-the-pinch', 1, 'SECTION 15 prints the engine''s choked-flow note for the invented Isiokpo trap at an isentropic exponent of 1.3. Which critical ratio does it name?', '["0.5774", "0.1126", "0.5457", "0.555556"]'::jsonb, 2, 'The note at 1.3, verbatim: "Choked flow: the pressure ratio 0.1126 is at or below the critical 0.5457, so the loss depends on the upstream pressure alone." At 1.135 the note names the critical 0.5774. 0.555556 is the pressure ratio of a trap discharging at 5 bar a.'),
  ('carbon', 'intermediate', 'module', 'm05-steam-condensate-and-the-pinch', 2, '5 bar a sits downstream of the invented 9 bar a trap at an exponent of 1.135. Which choked flag and hourly loss does SECTION 15 pair with it?', '["Choked true, 42.3520 kg an hour", "Choked false, 41.4785 kg an hour", "Choked false, 37.5765 kg an hour", "Choked true, 44.4620 kg an hour"]'::jsonb, 0, 'The 5 bar a row prints a pressure ratio of 0.555556 against a critical 0.577430, choked true and 42.3520 kg an hour, the same as the trap venting to atmosphere. 41.4785 and 37.5765 are the 6 and 7 bar a rows; 44.4620 is the trap at the superheated exponent of 1.3.'),
  ('carbon', 'intermediate', 'module', 'm05-steam-condensate-and-the-pinch', 3, 'At a downstream pressure of 8 bar a, how many tonnes of steam a year does SECTION 15 print the invented Isiokpo trap losing?', '["315.643", "348.419", "355.757", "244.029"]'::jsonb, 3, 'The 8 bar a row prints a pressure ratio of 0.888889, choked false, 29.0510 kg an hour and 244.029 tonnes a year. 315.643 is the 7 bar a row, 348.419 the 6 bar a row and 355.757 every choked row.'),
  ('carbon', 'intermediate', 'module', 'm05-steam-condensate-and-the-pinch', 4, 'The invented Isiokpo trap is given a downstream pressure of 9 bar a, the same as its upstream. What does steamTrapLoss answer?', '["REFUSED: A downstream pressure is required when the box is there. Left out, a trap venting to atmosphere (1.01325 bar a) is the stated default.", "REFUSED: The downstream pressure (9 bar a) is not below the upstream pressure (9 bar a), so no steam flows through the trap.", "No refusal: the pressure ratio is 1, above the critical 0.577430, so choked is false and the loss is 29.0510 kg an hour.", "REFUSED: The downstream pressure must be an absolute pressure of zero or more, in bar a."]'::jsonb, 1, 'SECTION 15 prints the 9 bar a call refused with that sentence. The required-box refusal answers a blank downstream box, the absolute-pressure refusal a downstream pressure of -1, and 29.0510 kg an hour is the 8 bar a row.'),
  ('carbon', 'intermediate', 'module', 'm05-steam-condensate-and-the-pinch', 5, 'steamTrapLoss is called for the invented Isiokpo trap with an isentropic exponent of 1. What does SECTION 15 print?', '["No refusal: an exponent of 1 is read as dry saturated steam and the loss prints at 42.3520 kg an hour.", "REFUSED: A discharge coefficient in (0, 1] is required and is not defaulted: it depends on the orifice and on how the trap failed.", "REFUSED: An isentropic exponent above 1 is required: about 1.3 for superheated steam and about 1.135 for dry saturated steam.", "REFUSED: An orifice diameter, an upstream pressure and a steam density are required."]'::jsonb, 2, 'SECTION 15 prints the same refusal for a blank exponent and for an exponent of 1. The discharge coefficient and orifice refusals answer those boxes left blank. 42.3520 kg an hour is the loss at the stated 1.135.'),
  ('carbon', 'intermediate', 'module', 'm05-steam-condensate-and-the-pinch', 6, 'No boiler efficiency is typed for the invented Isiokpo trap. Which result comes back?', '["355.757 tonnes of steam a year, with the fuel and the carbon 0.", "355.757 tonnes of steam a year, with fuel at a boiler efficiency of 1.", "REFUSED: A boiler efficiency in (0, 1] is required: the fuel saved depends on it and it is not assumed.", "355.757 tonnes of steam a year, with the fuel and the carbon none."]'::jsonb, 3, 'SECTION 15: with the boiler efficiency blank the trap still loses 355.757 tonnes a year, and the fuel and carbon are none. fuelNote: "Fuel needs a boiler efficiency in (0, 1]. It is not assumed to be 1." carbonNote names what carbon needs and calls it absent without them. The refusal quoted is condensateReturnValue''s, in SECTION 16.'),
  ('carbon', 'intermediate', 'module', 'm05-steam-condensate-and-the-pinch', 7, 'The hours argument is left out of the call entirely for the invented Isiokpo trap. What does SECTION 15 print?', '["The stated default of 8760 hours, 371.004 tonnes a year.", "REFUSED: Hours in service a year are required, between 0 and 8784. A blank is not read as a full year.", "The record''s 8400 hours in service, 355.757 tonnes a year.", "The superheated row''s figure, 373.481 tonnes of steam a year."]'::jsonb, 0, 'SECTION 15: hours left out of the call take the stated default of 8760, 371.004 tonnes a year. A blank hours box and a call with 9000 hours are refused: "Hours in service a year are required, between 0 and 8784. A blank is not read as a full year." 373.481 is the 1.3 exponent row at 8400 hours.'),
  ('carbon', 'intermediate', 'module', 'm05-steam-condensate-and-the-pinch', 8, 'SECTION 16 prices raising the invented Isiokpo condensate return from 0.35 to 0.65 with the treatment cost left blank. What does it print?', '["annualValue 175835.28 USD, complete true, and no note.", "annualValue 121403.28 USD, complete false, and a floor note.", "annualValue 121403.28 USD, complete true, and no note.", "annualValue 175835.28 USD, complete false, and a floor note."]'::jsonb, 1, 'With the treatment blank SECTION 16 prints annualValue 121403.28, complete false and the valueNote "A floor on the value: Treatment not repeated not priced. The treatment cost is the one usually left out." With treatment priced it prints 175835.28 and complete true.'),
  ('carbon', 'intermediate', 'module', 'm05-steam-condensate-and-the-pinch', 9, 'What carbon does the invented Isiokpo condensate case report once the treatment price is left blank?', '["none, since the value is not complete", "63.721, the trap''s figure for its boiler", "742.220 priced and 0.000 left blank", "742.220, the same as with the treatment priced"]'::jsonb, 3, 'SECTION 16 prints annualTonnesCo2e 742.220 in both columns, on the SYNTHETIC factor of 56.1 kg CO2e per GJ. The treatment line, annualValue and complete differ between the columns. 63.721 tCO2e is the trap of SECTION 15.'),
  ('carbon', 'intermediate', 'module', 'm05-steam-condensate-and-the-pinch', 10, 'The invented Isiokpo condensate case is called with a target return of 0.25 against the current 0.35. What does condensateReturnValue answer?', '["REFUSED: Return fractions must lie between 0 and 1.", "No refusal: a negative annualValue, with complete true and the fuel line printed below zero for the year.", "REFUSED: The target return (0.25) is below the current return (0.35). Returning less condensate is a cost, so there is nothing to value.", "REFUSED: A boiler efficiency in (0, 1] is required: the fuel saved depends on it and it is not assumed."]'::jsonb, 2, 'SECTION 16 prints the 0.25 target refused with that sentence, and SECTION 25 lists a target condensate return below the current one as refused. No negative annualValue is printed. A target of 1.2 draws the return-fraction refusal, and a blank boiler efficiency the boiler refusal.'),
  ('carbon', 'intermediate', 'module', 'm05-steam-condensate-and-the-pinch', 11, 'At a minimum approach of 20 C, which utility targets does SECTION 17 print for the four invented Isiokpo streams?', '["25.950 kW hot and 240.150 kW cold", "59.700 kW hot and 273.900 kW cold", "1.800 kW hot and 216.000 kW cold", "59.700 kW hot and 240.150 kW cold"]'::jsonb, 1, 'The 20 C row prints hot utility 59.700 kW and cold utility 273.900 kW. The 15 C row prints 25.950 and 240.150, and the 10 C row 1.800 and 216.000.'),
  ('carbon', 'intermediate', 'module', 'm05-steam-condensate-and-the-pinch', 12, 'SECTION 17 prints a threshold problem: one hot stream at 10 kW/K and one cold at 1 kW/K, at 10 C. Its heat flow is zero only at the top of the cascade. What does the engine report?', '["No pinch, with threshold problem true.", "A pinch at shifted 195.000 C, threshold false.", "A pinch at shifted 35.000 C, threshold true.", "No pinch, with threshold problem false."]'::jsonb, 0, 'SECTION 17 prints hot utility 0.000, cold utility 1470.000, pinch hot none and threshold problem true. The engine reports no pinch there: a zero at either end of the cascade is a threshold, and naming it a pinch would invent a constraint. SECTION 25: only an interior zero of the cascade is a pinch.'),
  ('carbon', 'intermediate', 'module', 'm05-steam-condensate-and-the-pinch', 13, 'SECTION 17 prints the engine''s note on the pinch. What does it say heat carried across the pinch costs?', '["One unit more hot utility, the cold utility unchanged.", "One unit more cold utility, the hot utility unchanged.", "Two units more hot utility and none of cold utility.", "One unit more hot utility and one unit more cold utility."]'::jsonb, 3, 'The note, verbatim: "Heat carried across the pinch costs twice: one unit more hot utility and one unit more cold utility." The note goes on to call the pinch the constraint.'),
  ('carbon', 'intermediate', 'module', 'm05-steam-condensate-and-the-pinch', 14, 'Which heat recovered figure goes with the 10 C row of the Isiokpo pinch targets?', '["561.000 kW", "527.250 kW", "585.150 kW", "586.950 kW"]'::jsonb, 2, 'The 10 C row prints heat recovered 585.150 kW. 561.000 is the 15 C row, 527.250 the 20 C row and 586.950 the total cold stream duty.'),
  ('carbon', 'intermediate', 'module', 'm05-steam-condensate-and-the-pinch', 15, 'In the SECTION 17 problem table at 15 C for the invented Isiokpo streams, where does the heat flow reach zero, and how is the pinch reported?', '["At shifted 155.500 C, the top of the cascade: 163.000 C hot side, 148.500 C cold side.", "At shifted 110.500 C, inside the range: 118.000 C hot side, 103.000 C cold side.", "At shifted 33.500 C, the bottom of the cascade: 41.000 C hot side, 32.000 C cold side.", "At shifted 111.500 C, inside the range: 118.000 C hot side, 108.000 C cold side."]'::jsonb, 1, 'SECTION 17: the heat flow is zero at shifted 110.500 C, inside the range: the pinch, 118.000 C on the hot side and 103.000 C on the cold side. The cascade starts at 155.500 with the hot utility 25.950 and ends at 33.500 with the cold utility 240.150. 108.000 C is the cold side pinch at 10 C.'),
  ('carbon', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'Follow the invented Isiokpo heater''s current reading of 5.5 percent oxygen through the oxygen table and the stack loss rows. Which pair does it become?', '["13.9199 percent excess air and 87.8476 percent on LHV", "32.1223 percent excess air and 86.4029 percent on LHV", "32.1223 percent excess air and 79.2343 percent on HHV", "21.2938 percent excess air and 86.4029 percent on LHV"]'::jsonb, 1, 'Excess air 32.1223 percent is the 5.5 row of the oxygen table; 86.4029 percent is the current row on LHV. The 2.8 target pairs 13.9199 with 87.8476, 79.2343 is that target on HHV, and 21.2938 goes with a 4 percent reading.'),
  ('carbon', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'Across the invented Isiokpo steam and stream calls, which one does the engine answer in part while naming the gap?', '["The condensate case with its boiler efficiency blank", "The condensate case with its treatment cost blank", "The trap with its isentropic exponent blank", "The pinch targets with the minimum approach blank"]'::jsonb, 1, 'The treatment-blank condensate case still prints a total and flags it as a floor (SECTION 16). The other three calls get no answer at all: SECTION 16 refuses a blank boiler efficiency, SECTION 15 a blank exponent, and SECTION 17 a blank minimum approach.'),
  ('carbon', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'A blank boiler efficiency reaches both the invented Isiokpo trap and the Isiokpo condensate case. What do SECTIONS 15 and 16 print?', '["The trap keeps its steam figure and leaves fuel and carbon none; the condensate call is refused.", "Both are refused, each with the message that a boiler efficiency in (0, 1] is required.", "The condensate case reports its water lines with fuel none; the trap call is refused outright.", "Both take a boiler efficiency of 1 and name it in a note beside the fuel and the carbon."]'::jsonb, 0, 'The trap row with no boiler efficiency keeps its 355.757 tonnes a year and prints fuel and carbon as none (SECTION 15). For condensateReturnValue the same blank is one of SECTION 16''s four refusals, so no value prints.'),
  ('carbon', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'Across the invented Isiokpo steam calls, which of these gaps does SECTION 15 or 16 answer with a stated default?', '["The trap''s hours box left blank, taken at 8760", "The condensate case''s hours box left blank, taken at 8400", "The trap''s hours left out of the call, taken at 8760", "The trap''s discharge coefficient left blank, taken at 1"]'::jsonb, 2, 'Of these gaps only one draws a default: the trap''s hours absent from the call, which SECTION 15 answers with 8760 and 371.004 tonnes a year. Both hours boxes, the trap''s and the condensate case''s, are refused when present but blank (SECTIONS 15 and 16), and the discharge coefficient refusal says it is not defaulted.'),
  ('carbon', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'Which of these Isiokpo figures is an engine output, where the digest marks the other three computed here?', '["The 8.4741 point LHV and HHV gap", "The trap''s extra 17.724 tonnes a year", "The shortcut''s 5923.008 GJ a year", "annualEnergySavedGJ 6742.370"]'::jsonb, 3, 'SECTION 14''s output table prints annualEnergySavedGJ 6742.370. The stack loss section marks the 8.4741 point gap computed here, SECTION 15 the 17.724 tonnes a year between exponents, and SECTION 14 the shortcut''s 5923.008 GJ, which the engine does not return.'),
  ('carbon', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'The invented Isiokpo trap''s downstream table in SECTION 15 ends with one sentence. Which?', '["At or below the critical ratio the downstream pressure lowers the loss; above it the loss does not move with the downstream pressure.", "At or below the critical ratio the loss does not move with the downstream pressure; above it the downstream pressure lowers the loss.", "Above the critical ratio the downstream pressure raises the loss, and at or below it the loss depends on the downstream pressure alone.", "At every ratio the loss moves with the downstream pressure, and the critical ratio only marks where the flow note changes its words."]'::jsonb, 1, 'SECTION 15 prints that sentence under the table: 42.3520 kg an hour at 1.01325, 3 and 5 bar a, all choked, then 41.4785, 37.5765 and 29.0510 at 6, 7 and 8 bar a, choked false.'),
  ('carbon', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'SECTION 14 prints a saving fraction for the invented Isiokpo tuning on HHV. Which two efficiencies is it computed from?', '["86.4029 and 87.8476, both on LHV", "77.9288 on HHV and 87.8476 percent on LHV", "77.9288 and 79.2343 percent, both on HHV", "86.4029 on LHV and 79.2343 on HHV"]'::jsonb, 2, 'SECTION 14: on HHV the same tuning is a saving fraction of 0.0164763814, computed from the two HHV efficiencies of the stack loss section, the current 77.9288 and the target 79.2343. A pair on mixed bases is refused: "The two efficiencies are on different bases (LHV and HHV) and cannot be compared."'),
  ('carbon', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'Four Isiokpo figures from SECTIONS 14 to 16 are set side by side. Which of them is an amount of carbon?', '["742.220 tCO2e a year from the condensate", "6742.370 GJ a year saved by tuning", "355.757 tonnes a year of trap steam", "13230.304 GJ a year from condensate"]'::jsonb, 0, 'SECTION 16 prints annualTonnesCo2e 742.220 on the SYNTHETIC factor. 6742.370 GJ is SECTION 14''s LHV energy saved, 355.757 tonnes a year is steam lost by the trap in SECTION 15, and 13230.304 GJ is SECTION 16''s energySavedGJPerYear.'),
  ('carbon', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'The stack loss section gives the invented Isiokpo heater a radiation and convection loss of 1.8 percent. Where does that figure come from?', '["It is the typical value energyEfficiency.PROPERTY_REFERENCE ships.", "The engine computes it from the heater''s surface and firing rate.", "It is the stack oxygen loss the excess air of 32.1223 percent gives.", "It is read off the heater vendor''s chart, invented for the course."]'::jsonb, 3, 'The stack loss section: radiation and convection loss 1.8 percent read off the heater vendor''s chart (invented). PROPERTY_REFERENCE ships flue gas cp, vapour cp and latent heat only, and the blank refusal says the chart against surface area and firing rate is one this module does not reproduce.'),
  ('carbon', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'The invented Isiokpo trap reports carbon only when three inputs are given. Which does its carbonNote name?', '["The discharge coefficient, the hours a year and an emission factor.", "The steam energy content, the boiler efficiency and an emission factor.", "The steam density, the boiler efficiency and the steam price a tonne.", "The isentropic exponent, the orifice and the steam energy content."]'::jsonb, 1, 'carbonNote, verbatim: "Carbon needs the steam energy content, the boiler efficiency and an emission factor." Without them the carbon is absent. At Isiokpo they are 2650 MJ a tonne, 0.83 and the SYNTHETIC 56.1 kg CO2e per GJ.'),
  ('carbon', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'Pricing a saving per tonne is governed by one of the rules in force. Which wording is it?', '["The cost per tonne of a saving sets its capital against one year''s saving, and needs no rate.", "The cost per tonne of a saving is the simple payback, and needs a life but no discount rate.", "The cost per tonne of a saving is the levelised abatementCost, and needs a life and a rate.", "A saving, its price and its factor may sit on different heating value bases if each is named."]'::jsonb, 2, 'SECTION 25 lists "The cost per tonne of a saving is the levelised abatementCost, and needs a life and a rate" and "A saving, its price and its factor declared on different heating value bases are refused".'),
  ('carbon', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'SECTION 17 prints the invented Isiokpo pinch at approaches of 10, 15 and 20 C. What does the pinch do across those rows?', '["The hot side stays at 118.000 C while the cold side reads 108.000, 103.000 and 98.000 C.", "Both sides stay put, 118.000 C on the hot side and 103.000 C on the cold side, at each row.", "The cold side stays at 103.000 C while the hot side reads 118.000, 110.500 and 98.000 C.", "The pinch appears only at 15 C; the 10 and 20 C rows print threshold problem true instead."]'::jsonb, 0, 'The three target rows print pinch hot 118.000 C each time and pinch cold 108.000, 103.000 and 98.000 C, with threshold problem false in every row. 110.500 is the shifted temperature of the 15 C zero.'),
  ('carbon', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'In the heater chain from stack oxygen to tuning, which input does SECTION 14 say is declared after a combustion test?', '["The current dry stack oxygen, 5.5 percent at Isiokpo.", "The target stack oxygen, 2.8 percent at Isiokpo.", "The stack temperature, 238 C at the invented heater.", "The minimum safe stack oxygen, 2 percent at Isiokpo."]'::jsonb, 3, 'SECTION 14 prints a minimum safe stack oxygen of 2 percent declared after a combustion test (invented), and refuses it blank: "A minimum safe stack oxygen is required and is not defaulted." SECTION 12 asks for a measured dry stack oxygen, the 2.8 percent target is checked against the declared floor, and the 238 C stack is an invented input of the stack loss section.'),
  ('carbon', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'A failed steam trap has its own rule in force. According to that row, what must a trap be given?', '["A downstream pressure, a discharge coefficient and a steam price for every tonne.", "A boiler efficiency for fuel and carbon, an isentropic exponent, and hours a year.", "A boiler efficiency, a declared safe floor and a radiation and convection loss.", "An emission factor, an orifice diameter and a year of 8760 hours in service."]'::jsonb, 1, 'SECTION 25: "A trap needs a boiler efficiency for fuel and carbon, an isentropic exponent, and hours a year", pointing at SECTION 15. The safe floor belongs to the tuning of SECTION 14 and the radiation loss to the stack loss section; 8760 hours is the stated default when hours are left out of the call.'),
  ('carbon', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'Every SECTION 17 target row for the four invented Isiokpo streams prints a balance check of 0.000. How does the digest define it?', '["(hot utility plus cold utility) less (hot stream duty plus cold stream duty)", "(hot utility plus cold stream duty) less (cold utility plus hot stream duty)", "(hot utility plus hot stream duty) less (cold utility plus cold stream duty)", "(hot stream duty plus cold utility) less (hot utility plus cold stream duty)"]'::jsonb, 2, 'SECTION 17: the balance check is (hot utility plus hot stream duty) less (cold utility plus cold stream duty): heat in less heat out, 0.000 when the targets close. Heat recovered is the hot streams'' duty less the cold utility, 801.150 less 240.150 is 561.000 kW at 15 C.'),
  ('carbon', 'intermediate', 'final', null, 1, 'In the SECTION 11 demand table, what unweighted c + h/4 + s - o/2 term does the C3H8 row of the invented Isiokpo fuel carry?', '["3.5", "2", "5", "0"]'::jsonb, 2, 'The C3H8 row reads 5 in the c + h/4 + s - o/2 column. CH4 reads 2, C2H6 3.5, and both inerts 0.'),
  ('carbon', 'intermediate', 'final', null, 2, 'SECTION 11 says the air''s nitrogen is the rest of the stoichiometric air. Which figure does it print for it, in kmol per kmol fuel?', '["9.975652", "8.999152", "7.886152", "0.015000"]'::jsonb, 2, 'SECTION 11: the air''s nitrogen is the rest of that air, 7.886152 (computed here; products.airN2PerKmolFuel 7.886152). 9.975652 is the stoichiometric air itself, 8.999152 the dry flue gas at 0 percent oxygen in SECTION 12, and 0.015000 the fuel''s own nitrogen.'),
  ('carbon', 'intermediate', 'final', null, 3, 'Which heating values does SECTION 11 print for the invented Isiokpo fuel gas as analysed, inerts included?', '["862.5564 LHV and 930.6273 HHV MJ per kmol", "802.6 LHV and 890.8 HHV MJ per kmol", "840.9925 LHV and 862.5564 HHV MJ per kmol", "840.9925 LHV and 930.6273 HHV MJ per kmol"]'::jsonb, 3, 'SECTION 11 prints lhvMJPerKmolFuel 840.9925 and hhvMJPerKmolFuel 930.6273. 862.5564 is the LHV with the CO2 taken out and the rest renormalised; 802.6 and 890.8 are FUEL_REFERENCE''s typical methane pair, held as H2.'),
  ('carbon', 'intermediate', 'final', null, 4, 'At which stack oxygen does SECTION 11 strike its flue gas mass balance, and what does each side weigh?', '["5.5 percent; 351.0222 kg per kmol of fuel on each side", "3 percent; 351.0222 kg per kmol of fuel on each side", "0 percent; 351.0222 kg in and 351.0222 kg out per kg of fuel", "3 percent; 351.0222 kg in, and less out once argon is dropped"]'::jsonb, 1, 'SECTION 11 strikes THE MASS BALANCE at 3 percent stack oxygen, per kmol of fuel: 351.0222 in, 351.0222 out, out less in 0.000001 (computed here). Air''s argon leaves inside the atmospheric nitrogen.'),
  ('carbon', 'intermediate', 'final', null, 5, 'Which rows of energyEfficiency.FUEL_REFERENCE carry the flag inert yes?', '["N2 and H2", "CO2 alone", "CO2 and N2", "CH4 and H2"]'::jsonb, 2, 'SECTION 1 prints inert yes on the Carbon dioxide (inert) and Nitrogen (inert) rows, each with 0 typical LHV and HHV. H2, Hydrogen, prints no with 241.8 LHV and 285.8 HHV MJ/kmol.'),
  ('carbon', 'intermediate', 'final', null, 6, 'The oxygen table''s top reading is 12 percent. How much excess air goes with it?', '["55.7461 percent", "121.0076 percent", "32.1223 percent", "20.946 percent"]'::jsonb, 1, 'The 12 row prints 121.0076 percent excess air and 22.046948 kmol of air per kmol fuel. 55.7461 is the 8 row and 32.1223 the 5.5 row; 20.946 percent is the bound in the refusal for a reading of all air.'),
  ('carbon', 'intermediate', 'final', null, 7, 'Which figure is the wet flue gas of the invented Isiokpo heater at its current 5.5 percent reading, in kmol per kmol fuel?', '["14.236563", "12.203563", "13.180063", "16.593191"]'::jsonb, 0, 'Wet flue gas 14.236563 sits beside dry flue gas 12.203563 and actual air 13.180063 on the 5.5 line. 16.593191 is the wet flue gas at 8 percent.'),
  ('carbon', 'intermediate', 'final', null, 8, 'At a dry reading of 2 percent, the invented burner''s safe floor, how much excess air does the oxygen table show?', '["32.1223 percent", "13.9199 percent", "55.7461 percent", "9.5230 percent"]'::jsonb, 3, '9.5230 percent, beside 10.925631 kmol of air per kmol fuel. 13.9199 is the Isiokpo 2.8 target, 32.1223 the current 5.5 reading and 55.7461 a reading of 8.'),
  ('carbon', 'intermediate', 'final', null, 9, 'Tuned to 2.8 percent and read on the higher heating value, how big is the heater''s total loss?', '["22.0712 percent", "12.1524 percent", "20.7657 percent", "13.5971 percent"]'::jsonb, 2, 'The target HHV row prints dry loss 7.7207, moisture 11.2450, radiation 1.8000, unburned 0.0000, total 20.7657 and efficiency 79.2343. 22.0712 is the current HHV total, 12.1524 the target LHV total and 13.5971 the current LHV total.'),
  ('carbon', 'intermediate', 'final', null, 10, 'At 5.5 percent oxygen the stack loss section weighs the invented Isiokpo flue gas per kmol of fuel. Which pair does it print?', '["363.6388 kg dry flue gas and 18.5068 kg moisture", "363.6388 kg dry flue gas and 36.6245 kg moisture", "36.6245 kg dry flue gas and 363.6388 kg moisture", "363.6388 kg dry flue gas and 2.033000 kg moisture"]'::jsonb, 1, 'The stack loss section prints dryFlueGasKgPerKmolFuel 363.6388 and moistureKgPerKmolFuel 36.6245 at 5.5 percent. 18.5068 is the fuel''s molar mass and 2.033000 the water in kmol.'),
  ('carbon', 'intermediate', 'final', null, 11, 'No stack temperature is entered for the heater. Which answer does the efficiency call give?', '["REFUSED: A stack temperature and a combustion air temperature are required.", "REFUSED: A radiation and convection loss is required and is not defaulted. It comes off a published chart against surface area and firing rate, which this module does not reproduce.", "No refusal: the typical 238 C is used and named in a note.", "REFUSED: A flue gas specific heat is required."]'::jsonb, 0, 'The stack loss section prints the blank stack temperature refused with that sentence. 238 C is the invented Isiokpo stack, an input and no default. The radiation refusal answers a blank radiation loss, and the specific heat refusal a blank flue gas cp.'),
  ('carbon', 'intermediate', 'final', null, 12, 'What dry flue gas loss does the heater''s 2.8 percent target row print on HHV?', '["9.0262 percent", "8.5436 percent", "11.2450 percent", "7.7207 percent"]'::jsonb, 3, 'The target HHV row carries a dry loss of 7.7207 beside a moisture loss of 11.2450. 9.0262 is the dry loss at 5.5 percent on HHV, and 8.5436 the target dry loss on LHV.'),
  ('carbon', 'intermediate', 'final', null, 13, 'Which of the four losses prints the same 1.8000 in every one of the invented heater''s four stack loss rows?', '["The moisture loss on each basis", "The radiation and convection loss", "The unburned and other loss", "The dry flue gas loss on LHV"]'::jsonb, 1, 'Radiation prints 1.8000 on all four rows: current and target, LHV and HHV. Moisture prints 1.8088 on LHV and 11.2450 on HHV, unburned 0.0000, and the LHV dry loss 9.9883 then 8.5436.'),
  ('carbon', 'intermediate', 'final', null, 14, 'stackLossEfficiency returns an LHV efficiency with a comparison warning. What does that warning say?', '["This efficiency is on LHV. An efficiency on the other basis is the same number less the latent heat, and the two may then be compared freely.", "This efficiency is on LHV. Convert it to HHV with the typical 890.8 before it is set against an efficiency on the other basis.", "This efficiency is on LHV. An efficiency on the other basis is a different number for the same heater and the two must not be compared.", "This efficiency is on LHV. On the other basis the same heater reads 8.4741 points higher, and the two must be compared that way."]'::jsonb, 2, 'The comparison warning on LHV, verbatim: "This efficiency is on LHV. An efficiency on the other basis is a different number for the same heater and the two must not be compared." The stack loss section prints the HHV figure 8.4741 points lower, 77.9288 against 86.4029.'),
  ('carbon', 'intermediate', 'final', null, 15, 'The heater''s flue gas specific heat is not supplied. Which answer does stackLossEfficiency give?', '["REFUSED: A flue gas specific heat is required.", "No refusal: the typical 1.1 kJ/kg K is used.", "REFUSED: A stack temperature and a combustion air temperature are required.", "No refusal: 1.95 is taken from the vapour."]'::jsonb, 0, 'A missing flue gas cp draws its own one-line refusal. The Isiokpo calls pass the typical 1.1, and 1.95 kJ/kg K belongs to water vapour.'),
  ('carbon', 'intermediate', 'final', null, 16, 'At a dry reading of 4 percent, how much air does the invented Isiokpo fuel take, in kmol per kmol fuel?', '["11.123347", "13.156347", "11.364257", "12.099847"]'::jsonb, 3, 'The 4 percent line carries actual air 12.099847, dry flue gas 11.123347 and wet flue gas 13.156347, with 21.2938 percent excess air. 11.364257 is the actual air at 2.8 percent.'),
  ('carbon', 'intermediate', 'final', null, 17, 'Held item H2 sets two computed-here figures beside the engine''s typical methane pair. Which?', '["A difference of 87.985, and 88.2 MJ for two moles of water condensed at the engine''s latent heat", "A corrected methane HHV that replaces 890.8 in FUEL_REFERENCE from this digest onward, graded", "A difference of 88.2, and 87.985 MJ for two moles of water condensed at the engine''s latent heat", "A difference of 88.2 that the course grades, and an ISO 6976 value of 87.985 to be filed instead"]'::jsonb, 2, 'SECTION 25 prints both as computed here: 88.2 between the typical LHV and HHV, and 87.985 MJ from 2 x 18.015 kg at 2442 kJ/kg. H2 is a stated limit; nothing in it is graded or corrected.'),
  ('carbon', 'intermediate', 'final', null, 18, 'In the SECTION 14 sweep for the invented Isiokpo heater, how much fuel a year does a 4.5 percent target save on LHV?', '["5214.422 GJ", "2782.362 GJ", "6742.370 GJ", "8337.934 GJ"]'::jsonb, 1, 'The 4.5 row prints target efficiency 86.9933, fuelSavingPercent 0.6786 and annualEnergySavedGJ 2782.362. 5214.422 is the 3.5 row, 6742.370 the 2.8 row and 8337.934 the 2.0 row, all against 410000 GJ a year (invented).'),
  ('carbon', 'intermediate', 'final', null, 19, 'The invented Isiokpo tuning sweep''s lowest target sits on the declared 2 percent floor. What target efficiency on LHV does it print there?', '["87.8476 percent", "88.1965 percent", "87.5160 percent", "86.9933 percent"]'::jsonb, 1, 'The 2.0 target prints 88.1965 percent and 8337.934 GJ a year. 87.8476 goes with 2.8, 87.5160 with 3.5 and 86.9933 with 4.5.'),
  ('carbon', 'intermediate', 'final', null, 20, 'What does the second sentence of the engine''s tuning method say subtracting the efficiency percentages does to the saving?', '["It overstates the saving.", "It leaves the saving on LHV unchanged.", "It doubles the saving on HHV alone.", "It understates the saving."]'::jsonb, 3, 'The second sentence ends on the word understates, and names the cause: a divisor of a hundred where the target efficiency belongs. On the Isiokpo figures the digest''s shortcut lands 819.363 GJ a year short.'),
  ('carbon', 'intermediate', 'final', null, 21, 'The engine''s tuning method opens by holding one thing fixed while fuel scales inversely with efficiency. What is it?', '["The duty", "The fuel burned", "The excess air", "The stack temperature"]'::jsonb, 0, 'The method''s first sentence says fuel scales inversely with efficiency at the same duty.'),
  ('carbon', 'intermediate', 'final', null, 22, 'The invented Isiokpo trap is called with no downstream pressure at all. Where does SECTION 15 say it is taken to discharge?', '["At 5 bar a downstream, still choked.", "At its critical ratio, 0.5774 of 9 bar a.", "To atmosphere, ATMOSPHERE_BAR_A, 1.01325 bar a.", "Nowhere: the call is refused as blank."]'::jsonb, 2, 'SECTION 15: with no downstream pressure given the trap vents to ATMOSPHERE_BAR_A, 1.01325 bar a. A downstream box present but blank is refused; a box left out takes the atmosphere default.'),
  ('carbon', 'intermediate', 'final', null, 23, 'Raise the invented Isiokpo trap''s downstream pressure to 6 bar a. What happens to choked, and to the year''s loss?', '["Choked true, 355.757 tonnes a year", "Choked false, 348.419 tonnes a year", "Choked false, 315.643 tonnes a year", "Choked true, 348.419 tonnes a year"]'::jsonb, 1, 'Its ratio, 0.666667, is above the critical 0.577430, so choked is false and the loss falls to 41.4785 kg an hour. Choked rows lose 355.757 tonnes; 315.643 goes with 7 bar a.'),
  ('carbon', 'intermediate', 'final', null, 24, 'SECTION 15 states the critical pressure ratio at or below which a trap''s flow is choked. Which expression is it?', '["(2/(k+1))^((k-1)/k)", "(2/(k-1))^(k/(k+1))", "(1/(k+1))^(k/(k-1))", "(2/(k+1))^(k/(k-1))"]'::jsonb, 3, 'SECTION 15: the flow is choked while the downstream pressure over the upstream is at or below the critical ratio (2/(k+1))^(k/(k-1)). The digest prints it as 0.577430 at k = 1.135 and 0.5457 at 1.3.'),
  ('carbon', 'intermediate', 'final', null, 25, 'The trap''s discharge coefficient is not given. Which answer does the engine give?', '["REFUSED: A discharge coefficient in (0, 1] is required and is not defaulted: it depends on the orifice and on how the trap failed.", "No refusal: the coefficient is taken at the record''s 0.72, the Isiokpo trap''s typed figure, and the loss prints at 42.3520 kg an hour as before.", "REFUSED: An orifice diameter, an upstream pressure and a steam density are required.", "No refusal: the coefficient is read as 1, and the fuel and carbon are marked as absent."]'::jsonb, 0, 'SECTION 15 prints the blank discharge coefficient refused with that sentence. 0.72 is the Isiokpo trap''s typed coefficient (invented). The orifice refusal answers a blank orifice.'),
  ('carbon', 'intermediate', 'final', null, 26, 'At the stated exponent of 1.135 and an invented 22 USD a tonne, what annual cost does SECTION 15 print for the trap''s lost steam?', '["8216.58 USD", "22176.00 USD", "7826.65 USD", "54432.00 USD"]'::jsonb, 2, 'The 1.135 row prints 355.757 tonnes a year and 7826.65 USD. 8216.58 is the 1.3 row, and 22176.00 and 54432.00 are SECTION 16''s raw water and treatment lines.'),
  ('carbon', 'intermediate', 'final', null, 27, 'SECTION 15 prints the trap''s carbon chain as relations. How is its 63.721 tCO2e a year formed?', '["355.757 t x 56.1 kg CO2e per GJ / 1000", "1135.851 GJ x 56.1 kg CO2e per GJ / 1000", "1135.851 GJ x 56.1 x 0.83 / 1000", "1192.439 GJ x 56.1 kg CO2e per GJ / 1000"]'::jsonb, 1, 'SECTION 15: annual tCO2e = GJ x kg per GJ / 1000 = 63.721, on the annual fuel 1135.851 GJ and the SYNTHETIC 56.1 kg CO2e per GJ. The boiler efficiency 0.83 enters one step earlier, in the fuel. 1192.439 GJ is the fuel of the 1.3 row.'),
  ('carbon', 'intermediate', 'final', null, 28, 'Switch the trap''s steam to superheated, exponent 1.3. What carbon a year does SECTION 15 then print, in tCO2e?', '["63.721", "56.1", "742.220", "66.896"]'::jsonb, 3, 'The 1.3 row prints 44.4620 kg an hour, 373.481 tonnes a year, 8216.58 USD, 1192.439 GJ and 66.896 tCO2e. 63.721 is the 1.135 row, 56.1 the SYNTHETIC kg CO2e per GJ, and 742.220 the condensate case.'),
  ('carbon', 'intermediate', 'final', null, 29, 'What does SECTION 15 compute from the engine''s figures for the gap between the 1.3 and 1.135 exponent rows of the trap?', '["17.724 tonnes a year less at 1.3, a ratio of 1.049821", "1.049821 tonnes a year more at 1.3, a ratio of 17.724", "17.724 tonnes a year more at 1.3, a ratio of 1.049821", "355.757 tonnes a year more at 1.3, a ratio of 0.5457"]'::jsonb, 2, 'SECTION 15: at the superheated exponent the same trap loses 17.724 tonnes a year more, a ratio of 1.049821 to the saturated figure (computed here). 373.481 against 355.757 tonnes a year.'),
  ('carbon', 'intermediate', 'final', null, 30, 'The choked-flow note for the invented Isiokpo trap names a pressure ratio of 0.1126. Which call is that ratio from?', '["The call at 3 bar a downstream", "The critical ratio at the saturated exponent", "The call with no downstream pressure given", "The call at 8 bar a downstream"]'::jsonb, 2, 'The trap''s record gives no downstream pressure, and with none given SECTION 15 takes it to vent to atmosphere, 1.01325 bar a; the choked-flow note printed for it names 0.1126. The downstream table prints 3 bar a at 0.333333 and 8 bar a at 0.888889, and the same note names the critical 0.5774 at 1.135.'),
  ('carbon', 'intermediate', 'final', null, 31, 'Someone types 9000 into the trap''s hours box. Which answer comes back?', '["No refusal: the hours are cut to 8784 and the loss is printed for a full year of service.", "REFUSED: Hours in service a year are required, between 0 and 8784. A blank is not read as a full year.", "No refusal: the stated default of 8760 hours is used, and the loss is 371.004 tonnes a year.", "REFUSED: An isentropic exponent above 1 is required: about 1.3 for superheated steam and about 1.135 for dry saturated steam."]'::jsonb, 1, '9000 is above the 8784 bound the refusal states, and the digest prints it refused in the blank''s words. Only hours left out of the call entirely reach the 8760 default.'),
  ('carbon', 'intermediate', 'final', null, 32, 'With the treatment cost priced on the invented Isiokpo condensate case, which line does SECTION 16 print as 54432.00 USD?', '["Raw water not bought", "Fuel not burned reheating makeup", "The trap''s annual steam cost", "Treatment not repeated"]'::jsonb, 3, 'SECTION 16 prints Fuel not burned reheating makeup 99227.28, Raw water not bought 22176.00 and Treatment not repeated 54432.00 USD. The trap''s cost, 7826.65 USD, is SECTION 15.'),
  ('carbon', 'intermediate', 'final', null, 33, 'A return fraction of 1.2 is typed as the target of the invented condensate case. Which answer comes back?', '["REFUSED: Return fractions must lie between 0 and 1.", "REFUSED: The target return (0.25) is below the current return (0.35). Returning less condensate is a cost, so there is nothing to value.", "No refusal: the return is capped at 1 and complete prints true.", "REFUSED: A boiler efficiency in (0, 1] is required: the fuel saved depends on it and it is not assumed."]'::jsonb, 0, 'SECTION 16 prints the target of 1.2 refused with "Return fractions must lie between 0 and 1." The target-below-current refusal answers a target of 0.25 against 0.35, and the boiler efficiency refusal a blank boiler efficiency.'),
  ('carbon', 'intermediate', 'final', null, 34, 'pinchTargets is handed streams whose supply and target temperatures are all equal. What does SECTION 17 print?', '["No refusal: both utilities print 0.000 kW and threshold problem prints true.", "REFUSED: A minimum approach temperature is required and must not be negative.", "REFUSED: No stream changes temperature, so there is nothing to target.", "No refusal: every stream is read as cold, and the cold utility is 0.000 kW."]'::jsonb, 2, 'SECTION 17 prints that refusal for a set of streams where nothing changes temperature. The minimum approach refusal answers a blank approach.'),
  ('carbon', 'intermediate', 'final', null, 35, 'Which pair of condensate figures does SECTION 16 print the same with the treatment cost priced and with it left blank?', '["40320.000 t of extra condensate and 13230.304 GJ saved a year", "175835.28 USD annualValue and complete true in both columns", "54432.00 USD of treatment and 742.220 tCO2e in both columns", "121403.28 USD annualValue and 13230.304 GJ saved a year"]'::jsonb, 0, 'Both columns print extraCondensateTonnesPerYear 40320.000 and energySavedGJPerYear 13230.304, and annualTonnesCo2e 742.220. Treatment not repeated is 54432.00 priced and none blank, and annualValue is 175835.28 against 121403.28, complete true against false.'),
  ('carbon', 'intermediate', 'final', null, 36, 'Four invented Isiokpo streams are printed in SECTION 17. Which one is cold, by the digest''s rule?', '["H2 lean oil cooler, 118 C to 41 C: its supply is above its target.", "C2 stabiliser feed, 57 C to 104 C: its supply is below its target.", "H1 compressor aftercooler, 163 C to 48 C: its CP is 3.15 kW/K.", "H2 lean oil cooler, 118 C to 41 C: its CP is 5.7 kW/K."]'::jsonb, 1, 'SECTION 17: a stream is hot when its supply is above its target. C2 goes from 57 to 104 C, so it is cold, as C1 is. H1 and H2 have supplies above their targets and are hot, whatever their CP.'),
  ('carbon', 'intermediate', 'final', null, 37, 'In the SECTION 17 problem table at 15 C for the invented Isiokpo streams, what surplus does the interval from shifted 148.500 C to 111.500 C carry?', '["22.050 kW", "-3.600 kW", "96.600 kW", "-44.400 kW"]'::jsonb, 3, 'The row prints CP hot 3.150000, CP cold 4.350000, surplus -44.400 and heat flow below 3.600. 22.050 is the interval above it, -3.600 the interval below, and 96.600 the interval from 110.500 to 64.500.'),
  ('carbon', 'intermediate', 'final', null, 38, 'Starting from the hot utility at the top of that 15 C cascade, what heat flow sits under the first interval?', '["48.000 kW", "22.050 kW", "25.950 kW", "3.600 kW"]'::jsonb, 0, 'The cascade starts from the hot utility, 25.950 kW, at the top; the first interval''s surplus is 22.050 kW, and the heat flow below it prints 48.000 kW. 3.600 kW is the heat flow below the second interval.'),
  ('carbon', 'intermediate', 'final', null, 39, 'A stream with a heat capacity flowrate of -2 is passed to pinchTargets. What does SECTION 17 print?', '["No refusal: a CP of -2 marks the stream as cold, and it is cascaded at 2 kW/K on the cold side of the table.", "REFUSED: A minimum approach temperature is required and must not be negative.", "REFUSED: A heat capacity flowrate cannot be negative. Whether a stream is hot or cold is set by its supply and target temperatures.", "REFUSED: No stream changes temperature, so there is nothing to target."]'::jsonb, 2, 'SECTION 17 prints the CP of -2 refused with that sentence, and SECTION 25 lists it among the rules in force. The approach refusal answers a blank minimum approach, and the last refusal a set of streams that never change temperature.'),
  ('carbon', 'intermediate', 'final', null, 40, 'SECTION 17''s threshold problem runs one hot and one cold stream at a 10 C minimum approach. What cold utility does it print?', '["1480.000 kW", "1470.000 kW", "1300.000 kW", "240.150 kW"]'::jsonb, 1, 'The threshold row prints hot utility 0.000, cold utility 1470.000, pinch hot none and threshold problem true. 1480.000 and 1300.000 are points on its heat flow table, and 240.150 kW is the Isiokpo cold utility at 15 C.'),
  ('carbon', 'intermediate', 'final', null, 41, 'How does SECTION 17 say the streams are shifted before the problem table is cascaded?', '["Hot streams up and cold streams down, by half the minimum approach.", "Hot streams down and cold streams up, by the whole minimum approach.", "Cold streams down by the whole minimum approach, hot streams unmoved.", "Hot streams down and cold streams up, by half the minimum approach."]'::jsonb, 3, 'SECTION 17: hot streams are shifted down and cold streams up by half the minimum approach; the cascade below already carries the hot utility at the top. At 15 C the heat flow is zero at shifted 110.500 C, reported as 118.000 C hot and 103.000 C cold.'),
  ('carbon', 'intermediate', 'final', null, 42, 'Tighten the minimum approach to 10 C. How much hot utility do the four invented Isiokpo streams then need?', '["1.800 kW", "25.950 kW", "59.700 kW", "0.000 kW"]'::jsonb, 0, '1.800 kW of hot utility and 216.000 kW of cold at 10 C, pinched at 118.000 C and 108.000 C. At 15 C the hot utility is 25.950 and at 20 C 59.700; the threshold case needs 0.000.');
